<?php
$title='Products';require __DIR__.'/inc/header.php';$pdo=db();$message='';
if(is_post()){verify_csrf();$action=(string)post('action','');
 if($action==='delete'){ $pdo->prepare('DELETE FROM products WHERE id=?')->execute([(int)post('id')]); flash('success','Product deleted.'); redirect('/admin/products.php'); }
 if($action==='remove_image'){ $pdo->prepare('DELETE FROM product_images WHERE id=?')->execute([(int)post('image_id')]); flash('success','Gallery image removed.'); redirect('/admin/products.php?edit='.(int)post('product_id')); }
 if($action==='delete_file'){ $st=$pdo->prepare('SELECT stored_path FROM product_files WHERE id=?');$st->execute([(int)post('file_id')]);$f=$st->fetch();if($f&&is_file($f['stored_path']))@unlink($f['stored_path']);$pdo->prepare('DELETE FROM product_files WHERE id=?')->execute([(int)post('file_id')]);flash('success','Protected download deleted.');redirect('/admin/products.php?edit='.(int)post('product_id')); }
 if($action==='save'){
  $id=(int)post('id',0);$name=trim((string)post('name'));$sku=trim((string)post('sku'));$cat=(int)post('category_id');$price=(float)post('price');$compare=post('compare_price')!==''?(float)post('compare_price'):null;$desc=(string)post('description');$short=trim((string)post('short_description'));$brand=trim((string)post('brand','PAROKO'));$warranty=trim((string)post('warranty'));$status=post('status')==='1'?1:0;$featured=post('featured')?1:0;$new=post('is_new')?1:0;$best=post('is_best_seller')?1:0;
  try{
   if($id){$old=$pdo->prepare('SELECT slug,sku FROM products WHERE id=?');$old->execute([$id]);$o=$old->fetch();$slug=$o['slug']??slugify($name).'-'.bin2hex(random_bytes(2));$pdo->prepare('UPDATE products SET category_id=?,brand=?,name=?,sku=?,description=?,short_description=?,price=?,compare_price=?,warranty=?,status=?,featured=?,is_new=?,is_best_seller=? WHERE id=?')->execute([$cat,$brand,$name,$sku,$desc,$short,$price,$compare,$warranty,$status,$featured,$new,$best,$id]);flash('success','Product updated.');}
   else{$slug=slugify($name).'-'.strtolower(bin2hex(random_bytes(2)));$pdo->prepare('INSERT INTO products(category_id,brand,name,slug,sku,description,short_description,price,compare_price,warranty,status,featured,is_new,is_best_seller) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$cat,$brand,$name,$slug,$sku,$desc,$short,$price,$compare,$warranty,$status,$featured,$new,$best]);$id=(int)$pdo->lastInsertId();flash('success','Product created.');}
   $variantId=(int)post('variant_id',0);
   $variantSku=trim((string)post('variant_sku',$sku.'-DEFAULT'));
   $variantColor=trim((string)post('variant_color','Black'));
   $variantSize=trim((string)post('variant_size','M'));
   $variantStock=(int)post('stock',10);
   $low=(int)post('low_stock_threshold',5);
   if($variantId){
       $pdo->prepare('UPDATE variants SET sku=?,color=?,size=?,price=?,compare_price=?,stock=?,low_stock_threshold=? WHERE id=? AND product_id=?')->execute([$variantSku,$variantColor,$variantSize,$price,$compare,$variantStock,$low,$variantId,$id]);
   }else{
       $pdo->prepare('INSERT INTO variants(product_id,sku,color,size,price,compare_price,stock,low_stock_threshold,status) VALUES(?,?,?,?,?,?,?,?,1)')->execute([$id,$variantSku,$variantColor,$variantSize,$price,$compare,$variantStock,$low]);
   }
   if(!empty($_FILES['gallery']['name'][0])){foreach($_FILES['gallery']['name'] as $i=>$n){$f=['name'=>$n,'type'=>$_FILES['gallery']['type'][$i],'tmp_name'=>$_FILES['gallery']['tmp_name'][$i],'error'=>$_FILES['gallery']['error'][$i],'size'=>$_FILES['gallery']['size'][$i]];try{$u=save_public_upload($f,['jpg','jpeg','png','webp','gif','svg'],12000000,'products');$pdo->prepare('INSERT INTO product_images(product_id,image,sort_order) VALUES(?,?,?)')->execute([$id,$u['path'],(int)$pdo->query('SELECT COALESCE(MAX(sort_order),0)+1 FROM product_images WHERE product_id='.(int)$id)->fetchColumn()]);}catch(Throwable $ex){$message.=$ex->getMessage().' ';}}}
   if(isset($_FILES['download_file'])&&($_FILES['download_file']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){try{$f=save_private_download($_FILES['download_file']);$pdo->prepare('INSERT INTO product_files(product_id,filename,stored_path,mime,size) VALUES(?,?,?,?,?)')->execute([$id,$f['filename'],$f['stored_path'],$f['mime'],$f['size']]);}catch(Throwable $ex){$message.=$ex->getMessage().' ';}}
   redirect('/admin/products.php?edit='.$id);
  }catch(Throwable $e){$message=$e->getMessage();}
 }
}
$cats=$pdo->query('SELECT * FROM categories WHERE status=1 ORDER BY type,sort_order')->fetchAll();
$products=$pdo->query('SELECT p.*,c.name category_name,(SELECT COALESCE(SUM(stock),0) FROM variants v WHERE v.product_id=p.id) stock FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();
$editId=(int)get('edit',0);if($editId){redirect('/admin/product-edit.php?id='.$editId);} $edit=null;$images=[];$files=[];$variant=null;if($editId){$st=$pdo->prepare('SELECT * FROM products WHERE id=?');$st->execute([$editId]);$edit=$st->fetch();$st=$pdo->prepare('SELECT * FROM product_images WHERE product_id=? ORDER BY sort_order,id');$st->execute([$editId]);$images=$st->fetchAll();$st=$pdo->prepare('SELECT * FROM product_files WHERE product_id=? ORDER BY id DESC');$st->execute([$editId]);$files=$st->fetchAll();$st=$pdo->prepare('SELECT * FROM variants WHERE product_id=? ORDER BY id LIMIT 1');$st->execute([$editId]);$variant=$st->fetch();}
$edit=$edit?:['id'=>0,'name'=>'','sku'=>'','brand'=>'PAROKO','category_id'=>'','price'=>'','compare_price'=>'','short_description'=>'','description'=>'','warranty'=>'','status'=>1,'featured'=>0,'is_new'=>0,'is_best_seller'=>0];$variant=$variant?:['id'=>0,'sku'=>($edit['sku']? $edit['sku'].'-DEFAULT':''),'color'=>'Black','size'=>'M','stock'=>10,'low_stock_threshold'=>5];
?>
