<div class="bg-white border rounded-2xl overflow-hidden soft"><div class="p-4 border-b flex items-center gap-2"><input id="productFilter" oninput="filterProducts()" placeholder="Search products..." class="flex-1 rounded-xl border-slate-200"><span class="text-xs text-slate-400"><?=count($products)?> products</span></div><div class="overflow-x-auto"><table class="w-full text-sm" id="productTable"><thead class="bg-slate-50"><tr><th class="p-3 text-left">Product</th><th class="p-3 text-left">Category</th><th class="p-3 text-left">Price</th><th class="p-3 text-left">Stock</th><th class="p-3"></th></tr></thead><tbody><?php foreach($products as $r):?><tr class="border-t product-row"><td class="p-3"><div class="font-bold product-name"><?=e($r['name'])?></div><div class="text-xs text-slate-400"><?=e($r['sku'])?></div></td><td class="p-3"><?=e($r['category_name'])?></td><td class="p-3 font-bold"><?=money((float)$r['price'])?></td><td class="p-3"><span class="<?=((int)$r['stock']<5?'text-rose-600':'text-emerald-600')?> font-bold"><?=$r['stock']?></span></td><td class="p-3 text-right"><a href="/admin/product-edit.php?id=<?=$r['id']?>" class="text-blue-600 font-black">Edit</a><form method="post" class="inline" onsubmit="return confirm('Delete this product?')"><?=csrf_input()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="ml-3 text-rose-600 font-black">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
<div id="editor" class="bg-white border rounded-2xl p-5 soft"><div class="font-black text-lg"><?=($edit['id']?'Edit':'Create')?> Product</div><form method="post" enctype="multipart/form-data" class="mt-4 space-y-3"><?=csrf_input()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)$edit['id'])?>"><input type="hidden" name="variant_id" value="<?=e((string)$variant['id'])?>"><div class="grid sm:grid-cols-2 gap-3"><input required name="name" value="<?=e($edit['name'])?>" placeholder="Product name" class="rounded-xl border-slate-200 sm:col-span-2"><input required name="sku" value="<?=e($edit['sku'])?>" placeholder="SKU" class="rounded-xl border-slate-200"><input name="brand" value="<?=e($edit['brand'])?>" placeholder="Brand" class="rounded-xl border-slate-200"><select required name="category_id" class="rounded-xl border-slate-200 sm:col-span-2"><option value="">Category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$edit['category_id']==$c['id']?'selected':''?>>[<?=e($c['type'])?>] <?=e($c['name'])?></option><?php endforeach;?></select><input required type="number" step="0.01" name="price" value="<?=e((string)$edit['price'])?>" placeholder="Price" class="rounded-xl border-slate-200"><input type="number" step="0.01" name="compare_price" value="<?=e((string)$edit['compare_price'])?>" placeholder="Compare price" class="rounded-xl border-slate-200"><input name="warranty" value="<?=e($edit['warranty'])?>" placeholder="Warranty" class="rounded-xl border-slate-200 sm:col-span-2"></div><input name="short_description" value="<?=e($edit['short_description'])?>" placeholder="Short description" class="w-full rounded-xl border-slate-200"><label class="text-xs font-bold text-slate-500">Product Description / HTML</label><?php require __DIR__.'/rich_editor.php'; rich_editor('description',(string)$edit['description'],'productEditor');?><div class="rounded-2xl bg-slate-50 border p-4"><div class="font-black">Default Variant / Inventory</div><div class="grid grid-cols-2 gap-2 mt-3"><input name="variant_sku" value="<?=e($variant['sku'])?>" placeholder="Variant SKU" class="rounded-xl border-slate-200"><input name="variant_color" value="<?=e($variant['color'])?>" placeholder="Color" class="rounded-xl border-slate-200"><input name="variant_size" value="<?=e($variant['size'])?>" placeholder="Size" class="rounded-xl border-slate-200"><input name="stock" type="number" value="<?=e((string)$variant['stock'])?>" placeholder="Stock" class="rounded-xl border-slate-200"><input name="low_stock_threshold" type="number" value="<?=e((string)$variant['low_stock_threshold'])?>" placeholder="Low stock threshold" class="rounded-xl border-slate-200 col-span-2"></div></div><div><label class="text-xs font-bold text-slate-500">Gallery images — choose files</label><input type="file" name="gallery[]" multiple accept="image/*" class="mt-1 w-full rounded-xl border p-3 bg-white"></div><?php if($images):?><div class="grid grid-cols-4 gap-2"><?php foreach($images as $im):?><div class="relative"><img src="<?=e($im['image'])?>" class="aspect-square object-cover rounded-xl border"><form method="post" class="absolute top-1 right-1"><?=csrf_input()?><input type="hidden" name="action" value="remove_image"><input type="hidden" name="image_id" value="<?=$im['id']?>"><input type="hidden" name="product_id" value="<?=$edit['id']?>"><button class="w-7 h-7 bg-rose-600 text-white rounded-full">×</button></form></div><?php endforeach;?></div><?php endif;?><div class="rounded-2xl border border-blue-100 bg-blue-50 p-4"><div class="font-black text-blue-950">Protected digital product file</div><div class="text-xs text-blue-700 mt-1">ZIP is stored outside public uploads and can only be downloaded by an authenticated customer who purchased this product.</div><input type="file" name="download_file" accept=".zip,application/zip" class="mt-3 w-full rounded-xl border p-3 bg-white"><a href="/admin/media.php" class="inline-block mt-2 text-xs text-blue-700 font-bold">Open Media Library</a><?php if($files):?><div class="mt-3 space-y-2"><?php foreach($files as $f):?><div class="flex items-center justify-between bg-white rounded-xl p-3"><div><div class="font-bold text-sm"><?=e($f['filename'])?></div><div class="text-xs text-slate-400"><?=number_format($f['size']/1048576,2)?> MB · <?=e($f['created_at'])?></div></div><form method="post" onsubmit="return confirm('Delete protected file?')"><?=csrf_input()?><input type="hidden" name="action" value="delete_file"><input type="hidden" name="file_id" value="<?=$f['id']?>"><input type="hidden" name="product_id" value="<?=$edit['id']?>"><button class="text-xs text-rose-600 font-bold">Delete</button></form></div><?php endforeach;?></div><?php endif;?></div><div class="flex flex-wrap gap-4 text-sm"><label><input type="checkbox" name="featured" <?=$edit['featured']?'checked':''?>> Featured</label><label><input type="checkbox" name="is_new" <?=$edit['is_new']?'checked':''?>> New</label><label><input type="checkbox" name="is_best_seller" <?=$edit['is_best_seller']?'checked':''?>> Best Seller</label><select name="status" class="rounded-xl border-slate-200"><option value="1" <?=$edit['status']?'selected':''?>>Published</option><option value="0" <?=!$edit['status']?'selected':''?>>Hidden</option></select></div><button class="shine grad600 text-white w-full py-3 rounded-xl font-black">Save Product</button></form></div></div>
<script>function filterProducts(){const q=(document.getElementById('productFilter').value||'').toLowerCase();document.querySelectorAll('.product-row').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')}</script>
